function makePts(dx, dy, num, f) {
	let arr = [];
	for (let i = 0; i <= num*2*f; i++) {
		const a = map(i, 0, num*2, 0, TAU);
		const x = cos(a) * dx/2;
		const y = sin(a) * dy/2;
		arr.push([x, y]);
	}
	return arr;
}

